  db_empty_title:       { en: "Start your research", hi: "अपना शोध शुरू करें", ml: "നിങ്ങളുടെ ഗവേഷണം ആരംഭിക്കുക", ta: "உங்கள் ஆராய்ச்சியைத் தொடங்குங்கள்", te: "మీ పరిశోధన ప్రారంభించండి", kn: "ನಿಮ್ಮ ಸಂಶೋಧನೆ ಪ್ರಾರಂಭಿಸಿ" },
  db_empty_desc:        { en: "Upload your insurance policy or rejection letter to begin", hi: "शुरू करने के लिए अपनी बीमा पॉलिसी या अस्वीकृति पत्र अपलोड करें", ml: "ആരംഭിക്കാൻ നിങ്ങളുടെ ഇൻഷുറൻസ് പോളിസി അല്ലെങ്കിൽ നിരസിക്കൽ കത്ത് അപ്‌ലോഡ് ചെയ്യുക", ta: "தொடங்க உங்கள் காப்பீட்டு பாலிசி அல்லது நிராகரிப்பு கடிதத்தைப் பதிவேற்றவும்", te: "ప్రారంభించడానికి మీ బీమా పాలసీ లేదా తిరస్కరణ లేఖను అప్‌లోడ్ చేయండి", kn: "ಪ್ರಾರಂಭಿಸಲು ನಿಮ್ಮ ವಿಮಾ ಪಾಲಿಸಿ ಅಥವಾ ತಿರಸ್ಕಾರ ಪತ್ರವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ" },
  db_upload_first_doc:  { en: "Upload first document", hi: "पहला दस्तावेज़ अपलोड करें", ml: "ആദ്യ രേഖ അപ്‌ലോഡ് ചെയ്യുക", ta: "முதல் ஆவணத்தைப் பதிவேற்றவும்", te: "మొదటి పత్రాన్ని అప్‌లోడ్ చేయండి", kn: "ಮೊದಲ ದಾಖಲೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ" },
