  tl_final_settlement:  { en: "Final settlement", hi: "अंतिम निपटान", ml: "അന്തിമ തീർപ്പ്", ta: "இறுதி தீர்வு", te: "తుది పరిష్కారం", kn: "ಅಂತಿಮ ಇತ್ಯರ್ಥ" },
  tl_ombudsman_filing:  { en: "Ombudsman filing", hi: "लोकपाल फाइलिंग", ml: "ഓംബുഡ്സ്മാൻ ഫയലിംഗ്", ta: "குறைதீர்ப்பாளர் தாக்கல்", te: "అంబుడ్స్‌మెన్ దాఖలు", kn: "ಓಂಬುಡ್ಸ್‌ಮನ್ ಸಲ್ಲಿಕೆ" },
  tl_file_immediately:  { en: "a GRO deadline within 5 days. File immediately!", hi: "5 दिनों के भीतर GRO समय-सीमा। तुरंत फाइल करें!", ml: "5 ദിവസത്തിനുള്ളിൽ GRO സമയപരിധി. ഉടൻ ഫയൽ ചെയ്യുക!", ta: "5 நாட்களுக்குள் GRO காலக்கெடு. உடனே தாக்கல் செய்யவும்!", te: "5 రోజుల్లో GRO గడువు. వెంటనే దాఖలు చేయండి!", kn: "5 ದಿನಗಳಲ್ಲಿ GRO ಗಡುವು. ತಕ್ಷಣ ಸಲ್ಲಿಸಿ!" },
  tl_no_claims_title:   { en: "No claims tracked yet", hi: "अभी तक कोई दावा ट्रैक नहीं किया गया", ml: "ഇതുവരെ ക്ലെയിമുകളൊന്നും ട്രാക്ക് ചെയ്തിട്ടില്ല", ta: "இன்னும் கோரிக்கைகள் கண்காணிக்கப்படவில்லை", te: "ఇంకా క్లెయిమ్‌లు ట్రాక్ చేయబడలేదు", kn: "ಇನ್ನೂ ಯಾವುದೇ ಕ್ಲೇಮ್‌ಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿಲ್ಲ" },
  tl_no_claims_desc:    { en: "Run a rejection audit to start tracking IRDAI deadlines", hi: "IRDAI समय-सीमाओं को ट्रैक करना शुरू करने के लिए अस्वीकृति ऑडिट चलाएँ", ml: "IRDAI സമയപരിധികൾ ട്രാക്ക് ചെയ്യാൻ തുടങ്ങാൻ ഒരു നിരസിക്കൽ ഓഡിറ്റ് നടത്തുക", ta: "IRDAI காலக்கெடுக்களைக் கண்காணிக்கத் தொடங்க நிராகரிப்பு தணிக்கையை இயக்கவும்", te: "IRDAI గడువులను ట్రాక్ చేయడం ప్రారంభించడానికి తిరస్కరణ ఆడిట్ చేయండి", kn: "IRDAI ಗಡುವುಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಲು ಪ್ರಾರಂಭಿಸಲು ತಿರಸ್ಕಾರ ಆಡಿಟ್ ಚಲಾಯಿಸಿ" },
  tl_audit_rejection_btn: { en: "Audit a Rejection", hi: "अस्वीकृति का ऑडिट करें", ml: "ഒരു നിരസിക്കൽ ഓഡിറ്റ് ചെയ്യുക", ta: "ஒரு நிராகரிப்பைத் தணிக்கை செய்", te: "తిరస్కరణను ఆడిట్ చేయండి", kn: "ತಿರಸ್ಕಾರವನ್ನು ಆಡಿಟ್ ಮಾಡಿ" },
