  tl_claim_rejected:    { en: "Claim rejected", hi: "दावा अस्वीकृत", ml: "ക്ലെയിം നിരസിച്ചു", ta: "கோரிக்கை நிராகரிக்கப்பட்டது", te: "క్లెయిమ్ తిరస్కరించబడింది", kn: "ಕ್ಲೇಮ್ ತಿರಸ್ಕರಿಸಲಾಗಿದೆ" },
