  tl_within_45:         { en: "Within 45 days of rejection", hi: "अस्वीकृति के 45 दिनों के भीतर", ml: "നിരസിക്കൽ 45 ദിവസത്തിനുള്ളിൽ", ta: "நிராகரிப்பு 45 நாட்களுக்குள்", te: "తిరస్కరణ 45 రోజుల్లో", kn: "ತಿರಸ್ಕಾರದ 45 ದಿನಗಳಲ್ಲಿ" },
